// Builds the PiB Connector zip and writes src/connector-bundle.generated.ts: the version (from the
// plugin header) and the sha256 of the zip this plugin serves. The CRM hands exactly this hash to a
// site's self/update, so the constants and the zip must come from the same build.
//
//   node scripts/connector-bundle.mjs [zipOutPath]
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { buildConnectorZip } from "../../pib-wp-connector/build.mjs";

const HEADER = fileURLToPath(new URL("../../pib-wp-connector/pib-connector/pib-connector.php", import.meta.url));
const GENERATED = fileURLToPath(new URL("../src/connector-bundle.generated.ts", import.meta.url));

export async function connectorHeaderVersion() {
  const php = await readFile(HEADER, "utf8");
  const match = /^\s*\*\s*Version:\s*(\d+\.\d+\.\d+)\s*$/m.exec(php);
  if (!match) throw new Error(`No Version: header in ${HEADER}`);
  return match[1];
}

export function renderBundle(version, sha256) {
  return `// Generated by scripts/connector-bundle.mjs (runs in \`pnpm build\`). Do not edit by hand.
export const BUNDLED_CONNECTOR_VERSION = ${JSON.stringify(version)};
export const BUNDLED_CONNECTOR_SHA256 = ${JSON.stringify(sha256)};
`;
}

/** Build the zip at `zipPath`, then write the constants. */
export async function writeConnectorBundle(zipPath) {
  const built = await buildConnectorZip(zipPath);
  const version = await connectorHeaderVersion();
  await writeFile(GENERATED, renderBundle(version, built.sha256));
  return { version, sha256: built.sha256, bytes: built.bytes, path: built.path };
}

const invokedDirectly = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (invokedDirectly) {
  const out = process.argv[2] ?? fileURLToPath(new URL("../dist/ui/pib-connector.zip", import.meta.url));
  writeConnectorBundle(out).then((r) => console.log(`Connector ${r.version} sha256 ${r.sha256} (${r.bytes} bytes) -> ${r.path}`));
}
